{"name": "create_generate_monthly_report_procedure", "query": "
-- ============================================================
-- STORED PROCEDURE: generate_monthly_report(report_date DATE)
-- Snapshots current DB statistics and returns the new report_id
-- ============================================================
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(p_report_date DATE)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_department_count  INTEGER;
    v_total_employees   INTEGER;
    v_avg_salary        DECIMAL(12, 2);
    v_report_id         INTEGER;
BEGIN
    -- Count distinct active departments
    SELECT COUNT(DISTINCT de.department_id)
    INTO v_department_count
    FROM employees.department_employee de
    WHERE de.to_date = '9999-01-01';

    -- Count active employees (those with a current dept assignment)
    SELECT COUNT(DISTINCT de.employee_id)
    INTO v_total_employees
    FROM employees.department_employee de
    WHERE de.to_date = '9999-01-01';

    -- Average salary across all employees with an active salary record
    SELECT ROUND(AVG(s.amount)::numeric, 2)
    INTO v_avg_salary
    FROM employees.salary s
    WHERE s.to_date = '9999-01-01';

    -- Insert summary and capture the generated PK
    INSERT INTO employees.monthly_reports
        (report_date, department_count, total_employees, avg_salary, generated_at)
    VALUES
        (p_report_date, v_department_count, v_total_employees, v_avg_salary, now())
    RETURNING report_id INTO v_report_id;

    RAISE NOTICE 'Monthly report generated — id: %, date: %, depts: %, employees: %, avg_salary: %',
        v_report_id, p_report_date, v_department_count, v_total_employees, v_avg_salary;

    RETURN v_report_id;
END;
$$;

COMMENT ON FUNCTION employees.generate_monthly_report(DATE) IS
    'Generates a monthly executive report snapshot and returns its report_id';
"}

{"name": "create_high_salary_alert_trigger", "query": "
-- ============================================================
-- TRIGGER FUNCTION: fn_high_salary_alert
-- Fires on INSERT into employees.salary when amount > 120,000
-- ============================================================
CREATE OR REPLACE FUNCTION employees.fn_high_salary_alert()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts
            (employee_id, salary_amount, alert_date, status)
        VALUES
            (NEW.employee_id, NEW.amount, CURRENT_DATE, 'new');

        RAISE NOTICE 'HIGH SALARY ALERT — employee_id: %, amount: $%',
            NEW.employee_id, NEW.amount;
    END IF;

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION employees.fn_high_salary_alert() IS
    'Trigger function: inserts a salary_alert row when a salary > $120,000 is recorded';

-- ============================================================
-- TRIGGER: high_salary_alert
-- Bound to INSERT on employees.salary
-- ============================================================
DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;

CREATE TRIGGER high_salary_alert
    AFTER INSERT ON employees.salary
    FOR EACH ROW
    EXECUTE FUNCTION employees.fn_high_salary_alert();

COMMENT ON TRIGGER high_salary_alert ON employees.salary IS
    'Fires after each INSERT; creates an alert when salary amount exceeds $120,000';
"}

